// Fusionne les métadonnées de route avec la réponse Mapbox
const routeMeta = $('Define City Routes').item.json;
const apiResp   = $json;

const route   = (apiResp.routes || [])[0] || {};
const dur     = route.duration         || 0;
const durTyp  = route.duration_typical || dur;

return [{
  json: {
    city:                     routeMeta.city,
    route_name:               routeMeta.route_name,
    origin_latitude:          routeMeta.lat1,
    origin_longitude:         routeMeta.lon1,
    destination_latitude:     routeMeta.lat2,
    destination_longitude:    routeMeta.lon2,
    distance_meters:          route.distance || 0,
    duration_seconds:         dur,
    duration_typical_seconds: durTyp,
    delay_seconds:            dur - durTyp,
    raw_payload:              JSON.stringify(apiResp)
  }
}];
